"""Level Factory 0.259.0: the panel's walk builds the chosen layout's shell before it locks it (a lock taken first held
yesterday's shell, and every walk after a tool change refused its export: "collision_fingerprint changed after art
pass").

What it changes (anchored; each file pinned by hash; nothing written on a miss):
  * packages/service/walking.py, tests/service/test_walking.py, tests/service/test_revise.py -- edited.
  * VERSION 0.258.0 -> 0.259.0, CHANGELOG.

Generated by `patches/lf_shell_before_lock/gen_lf_shell_before_lock.py` from a proven clone.

    python patches/patch_lf_shell_before_lock.py
"""
import hashlib
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[1]
LF = ROOT / "level_factory"
PINS = {'packages/service/walking.py': '6259bbad8d822cce', 'tests/service/test_walking.py': '06e83f477abb7363', 'tests/service/test_revise.py': '7e0a4eae10ee3af1'}
EDITS = {'packages/service/walking.py': [('lines 63-66', '    cancel = run_dir / "cancel"\n    legs = [("import", ["-C", str(ws), "batch", "create", str(batch_path)]),\n            ("brief", ["-C", str(ws), "approve", mission, "brief_approved", "--by", "panel", "--note", AUTOMATIC]),\n            ("lock", ["-C", str(ws), "approve", mission, "functional_shell_locked", "--by", "panel",\n', '    cancel = run_dir / "cancel"\n    # THE SHELL BEFORE THE LOCK (0.259.0). The lock records the chosen layout\'s shell AS IT STANDS -- its collision,\n    # anchors and interactives -- and the art leg rebuilds that shell first wherever a tool changed it. Locked\n    # before the rebuild, the lock held yesterday\'s shell and the export refused today\'s: walking seed 9205 after\n    # Deli Counter 0.275.0-0.277.0 furnished its supermarket anew, "export blocked by functional regression:\n    # collision_fingerprint changed after art pass", every time, until somebody re-locked by hand. `make` already\n    # builds the shell before it locks; the panel\'s walk now does too.\n    legs = [("import", ["-C", str(ws), "batch", "create", str(batch_path)]),\n            ("brief", ["-C", str(ws), "approve", mission, "brief_approved", "--by", "panel", "--note", AUTOMATIC]),\n            ("shell", ["-C", str(ws), "run", mission]),\n            ("lock", ["-C", str(ws), "approve", mission, "functional_shell_locked", "--by", "panel",\n'), ('lines 70-71', '    said = {"import": "Reading revision %d of the level" % doc["revision"], "brief": "Recording the brief",\n            "lock": "Locking the chosen layout",\n', '    said = {"import": "Reading revision %d of the level" % doc["revision"], "brief": "Recording the brief",\n            "shell": "Building the chosen layout\'s shell",\n            "lock": "Locking the chosen layout",\n')], 'tests/service/test_walking.py': [('lines 67-69', '    assert [a[2] for a in calls] == ["approve", "approve", "run", "walk"]\n    assert calls[0][3:5] == ["walker_001", "brief_approved"] and calls[1][4] == "functional_shell_locked"\n    for gate in calls[:2]:\n', '    # 0.259.0: the shell is built before it is locked\n    assert [a[2] for a in calls] == ["approve", "run", "approve", "run", "walk"]\n    assert calls[0][3:5] == ["walker_001", "brief_approved"] and calls[2][4] == "functional_shell_locked"\n    for gate in (calls[0], calls[2]):\n'), ('lines 71-71', '    assert calls[2][-2:] == ["--art", "--gameplay"] and "--play" not in calls[3]\n', '    assert calls[1][2:] == ["run", "walker_001"]\n    assert calls[3][-2:] == ["--art", "--gameplay"] and "--play" not in calls[4]\n'), ('lines 105-105', '        return 4 if argv[2:3] == ["run"] else _fake(calls)(argv, log, cancel_file=cancel_file)\n', '        return 4 if argv[2:3] == ["run"] and "--art" in argv else _fake(calls)(argv, log, cancel_file=cancel_file)\n'), ('lines 108-109', '    assert e.value.code == "leg_failed" and "art exited 4" in str(e.value)\n\n', '    assert e.value.code == "leg_failed" and "art exited 4" in str(e.value)\n\n\ndef test_the_shell_is_built_before_it_is_locked(level):\n    """0.259.0: the lock records the shell as it stands, so it must stand rebuilt -- locked first, a tool change that\n    re-furnished a building made every walk\'s export refuse its own art pass ("collision_fingerprint changed after\n    art pass"). A shell that fails stops the walk before anything is locked. FAILS ON 0.258.0."""\n    got, run_dir, ws = level\n    calls = []\n    _workspace(level, calls)\n\n    def leg(argv, log, *, cancel_file, on_poll=None):\n        return 4 if argv[2:3] == ["run"] and "--art" not in argv else _fake(calls)(argv, log, cancel_file=cancel_file)\n    with pytest.raises(layouts.LayoutError) as e:\n        walking.walk(got["path"], EventSink(run_dir, "r", "w"), run_dir, leg=leg)\n    assert e.value.code == "leg_failed" and "shell exited 4" in str(e.value)\n    assert not [a for a in calls if "functional_shell_locked" in a]\n\n')], 'tests/service/test_revise.py': [('lines 91-91', '    assert calls[0][2:4] == ["batch", "create"] and [a[2] for a in calls[1:]] == ["approve", "approve", "run", "walk"]\n', '    # 0.259.0: the shell is built before it is locked\n    assert calls[0][2:4] == ["batch", "create"] and [a[2] for a in calls[1:]] == ["approve", "run", "approve", "run",\n                                                                                 "walk"]\n')]}
NEW_FILES = {}
CHANGELOG = '## [0.259.0] - the panel\'s walk builds the chosen layout\'s shell before it locks it\n\nOn 2026-10-27, rebuilding the walker\'s seed 9205 after Deli Counter 0.275.0-0.277.0 had furnished its supermarket\nanew, the panel\'s walk legs (import, brief, lock, art, walk) failed at export: "export blocked by functional\nregression: collision_fingerprint changed after art pass".\n\nThe functional lock records the chosen layout\'s shell AS IT STANDS: its collision, anchors and interactives. The art\nleg rebuilds that shell first wherever a tool changed it. So a lock taken before the rebuild held yesterday\'s shell,\nand the regression gate refused today\'s, correctly, on every walk after a tool update until somebody re-locked by\nhand. That is an intervention a level pays for every tool release that touches a shell. `make` already builds the\nshell before it locks.\n\n### Changed\n- **`packages/service/walking.py`**: the walk\'s legs are import, brief, **shell** (`run <mission>`, "Building the\n  chosen layout\'s shell"), lock, art, walk.\n  - A shell that fails stops the walk before anything is locked.\n  - An unchanged shell is all cache hits, so the leg costs a walk with no tool change nothing.\n\n### Tests\n- `tests/service/test_walking.py`:\n  - the legs in their new order;\n  - a failing shell stops the walk with nothing locked (fails on 0.258.0);\n  - a failed art leg is still named.\n- `tests/service/test_revise.py`: the walk of the current revision runs the shell leg.\n\n'
OLD_VERSION, NEW_VERSION = '0.258.0', '0.259.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        # 0.243.0 adds whole folders (apps/godot/): a new file's folder is made, never assumed
        (LF / name).parent.mkdir(parents=True, exist_ok=True)
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
